// ============================================================================
// RFFE_apb: APB4 register wrapper around RFFE_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/RFFE.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/RFFE.md
// ============================================================================
module RFFE_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sclk,
  output logic sdata_o,
  output logic sdata_oe,
  input logic sdata_i
);
  localparam logic [31:0] ID_VALUE = 32'h52460200;

  // ---------------- core ----------------
  logic [3:0]    c_cfg_div;
  logic          c_cmd_valid;
  logic          c_cmd_ready;
  logic [2:0]    c_cmd_type;
  logic [3:0]    c_cmd_sa;
  logic [15:0]   c_cmd_addr;
  logic [3:0]    c_cmd_bc;
  logic          c_wr_valid;
  logic          c_wr_ready;
  logic [7:0]    c_wr_data;
  logic          c_rd_valid;
  logic [7:0]    c_rd_data;
  logic          c_rd_perr;
  logic          c_done;
  logic          c_done_perr;
  logic          c_busy;
  RFFE_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_div(c_cfg_div),
    .sclk(sclk),
    .sdata_o(sdata_o),
    .sdata_oe(sdata_oe),
    .sdata_i(sdata_i),
    .cmd_valid(c_cmd_valid),
    .cmd_ready(c_cmd_ready),
    .cmd_type(c_cmd_type),
    .cmd_sa(c_cmd_sa),
    .cmd_addr(c_cmd_addr),
    .cmd_bc(c_cmd_bc),
    .wr_valid(c_wr_valid),
    .wr_ready(c_wr_ready),
    .wr_data(c_wr_data),
    .rd_valid(c_rd_valid),
    .rd_data(c_rd_data),
    .rd_perr(c_rd_perr),
    .done(c_done),
    .done_perr(c_done_perr),
    .busy(c_busy)
  );

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] r_CFG;   // 12'h014 CFG
  logic [26:0] h_CMD;   // 12'h018 CMD holding register
  logic [7:0] h_WR;   // 12'h01C WR holding register
  logic [8:0] h_RD;   // 12'h020 RD holding register
  logic full_CMD;
  logic full_WR;
  logic avail_RD;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 4'h7;
      h_CMD <= '0;
      h_WR <= '0;
      h_RD <= '0;
      full_CMD <= 1'b0;
      full_WR <= 1'b0;
      avail_RD <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[6] && !full_CMD) h_CMD <= (h_CMD & ~wmask[26:0]) | (PWDATA[26:0] & wmask[26:0]);
      if (wr && hit[6] && !full_CMD) full_CMD <= 1'b1;
      else if (full_CMD && c_cmd_ready) full_CMD <= 1'b0;
      if (wr && hit[7] && !full_WR) h_WR <= (h_WR & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[7] && !full_WR) full_WR <= 1'b1;
      else if (full_WR && c_wr_ready) full_WR <= 1'b0;
      if (c_rd_valid && (!avail_RD || (rd && hit[8]))) begin
        h_RD[7:0] <= c_rd_data[7:0];
        h_RD[8:8] <= c_rd_perr;
        avail_RD <= 1'b1;
      end else if (rd && hit[8]) avail_RD <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_div = r_CFG[3:0];
  assign c_cmd_type[2:0] = h_CMD[2:0];
  assign c_cmd_sa[3:0] = h_CMD[6:3];
  assign c_cmd_addr[15:0] = h_CMD[22:7];
  assign c_cmd_bc[3:0] = h_CMD[26:23];
  assign c_wr_data[7:0] = h_WR[7:0];
  assign c_cmd_valid = full_CMD;
  assign c_wr_valid = full_WR;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = full_CMD & c_cmd_ready;
    irq_set[2] = wr & (hit[6]) & full_CMD;
    irq_set[3] = full_WR & c_wr_ready;
    irq_set[4] = wr & (hit[7]) & full_WR;
    irq_set[5] = c_rd_valid & (~avail_RD | (rd & hit[8]));
    irq_set[6] = c_rd_valid & avail_RD & ~(rd & hit[8]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [2:0] flags = {avail_RD, full_WR, full_CMD};

  // ---------------- read mux ----------------
  logic [31:0] rdata;
  always_comb begin
    rdata = '0;
    case (PADDR[11:2])
      10'd0: rdata = ID_VALUE;
      10'd1: rdata = 32'(irq_status);
      10'd2: rdata = 32'(irq_enable);
      10'd3: rdata = 32'(flags);
      10'd4: rdata = scratch;
      10'd5: rdata = 32'(r_CFG);
      10'd6: rdata = 32'(h_CMD);
      10'd7: rdata = 32'(h_WR);
      10'd8: rdata = 32'(h_RD);
      10'd9: rdata = 32'({c_done_perr, c_busy});
      default: rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? rdata : '0;
endmodule
